(function(g){'use strict';const D=g.TLS_DATA,C=g.TLS_CORE,G=g.TLS_GAME,$=s=>document.querySelector(s);let confirmAction=null,storyStep=0;const stories=['There was pain. Then nothing. When Darwin opens his eyes, cold earth presses against his palms and a river speaks somewhere in the dark.','His pockets are empty. A translucent symbol burns at the edge of his vision: ANALYSE. Beneath it, another impossible word: SHOP.','Whatever brought him here left no answers. Survival must come first.'];
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1900)}function fmtTime(m){let h=Math.floor(m/60)%24;return`${String(h).padStart(2,'0')}:${String(Math.floor(m%60)).padStart(2,'0')}`}
function icon(id,art=false){return`<canvas class="item-sprite${art?' art':''}" width="24" height="24" data-icon="${id}"></canvas>`}function paintIcons(){document.querySelectorAll('canvas[data-icon]').forEach(c=>{let x=c.getContext('2d'),id=c.dataset.icon;x.imageSmoothingEnabled=false;x.clearRect(0,0,24,24);let p=(a,b,w,h,col)=>{x.fillStyle=col;x.fillRect(a,b,w,h)};if(id==='branch'||id==='log'||id==='kindling'){p(4,15,17,4,'#4b2e1f');p(5,12,15,4,'#98603b');p(15,7,3,8,'#5d3a25');p(17,5,4,4,'#5f8b45')}else if(id==='stone'||id==='stone_blade'){p(3,13,18,7,'#53605b');p(6,7,13,9,'#899188');p(9,6,7,3,'#b5b9a8')}else if(id==='fiber'||id==='cord'||id==='rope'){x.strokeStyle='#a8bd62';x.lineWidth=3;x.beginPath();x.arc(12,12,7,0,Math.PI*1.8);x.stroke();p(11,4,3,16,'#6f8e4d')}else if(id==='berry'){p(5,10,14,10,'#376b40');p(7,7,10,8,'#568b4e');p(7,11,5,5,'#c44f64');p(14,14,5,5,'#e16a6f')}else if(id==='water_dirty'||id==='bottle'||id==='filter'){p(8,3,8,3,'#a8d5cf');p(6,6,12,16,'#4c8e9a');p(8,9,8,10,'#7cc3c4');p(9,3,6,2,'#d4eee6')}else if(id==='knife'||id==='hatchet'||id==='saw'||id==='firestarter'||id==='fishing'){p(5,16,5,7,'#765038');p(9,5,4,13,'#a9b5aa');p(12,3,8,6,'#d0d4bd')}else if(id==='ration'){p(4,5,16,16,'#b8893e');p(7,8,10,4,'#eed083');p(8,14,8,4,'#725b34')}else if(id==='tarp'||id==='mat'){p(3,6,18,14,'#557b58');p(6,9,12,8,'#789b65')}else{p(5,5,14,14,'#b6944d')}})}
function hud(){let s=G.state;if(!s)return;$('#day').textContent=`DAY ${s.world.day}`;$('#clock').textContent=fmtTime(s.world.minutes);$('#weather').textContent=(s.world.weather==='Rain'?'☂ ':s.world.weather==='Cold Wind'?'≋ ':'☀ ')+s.world.weather.toUpperCase();$('#level').textContent=`LV. ${s.player.level}`;$('#rank').textContent=`RANK ${['I','II','III','IV','V','VI','VII','VIII','IX','X'][s.player.rank-1]} • ${s.player.rank===1?'STRANDED':s.player.rank===2?'PATHFINDER':'SURVIVOR'}`;let need=C.xpNeeded(s.player.level);$('#xpBar').style.width=(s.player.xp/need*100)+'%';$('#xpText').textContent=`${s.player.xp} / ${need} XP`;let defs=[['health','♥','#bf5547'],['energy','ϟ','#d5b64f'],['hunger','●','#cc843f'],['thirst','◆','#57999f'],['temperature','◉','#9eb672']];$('#meters').innerHTML=defs.map(([k,i,c])=>`<div class="vital" style="--c:${c}"><i>${i}</i><div><label>${k.toUpperCase()}</label><div class="bar"><b style="width:${k==='temperature'?(s.stats[k]-34)/4*100:s.stats[k]}%"></b></div></div><em>${k==='temperature'?s.stats[k].toFixed(1)+'°':Math.round(s.stats[k])}</em></div>`).join('');$('#condition').textContent=s.stats.health<35?'Critical':s.stats.thirst<25?'Dehydrated':s.stats.energy<20?'Exhausted':s.stats.temperature<35.5?'Hypothermic':'Stable';let q=s.quests.find(q=>q.id===s.activeQuest&&!q.claimed)||s.quests.find(q=>!q.claimed);if(q){$('#activeQuestTitle').textContent=q.title;$('#activeQuestDesc').textContent=q.desc;$('#activeQuestProgress').innerHTML=q.objectives.map(o=>`<div class="qrow"><span><i>${o.label}</i><b>${o.current}/${o.target}</b></span><div class="mini"><i style="width:${o.current/o.target*100}%"></i></div></div>`).join('')}$('#eventLog').innerHTML=s.log.slice(0,5).map(l=>`<div><time>${l.time}</time>${l.text}</div>`).join('');let quick=['branch','stone','fiber','berry','water_dirty','knife','hatchet','ration'];$('#quickbar').innerHTML=quick.map((id,i)=>`<div class="slot" title="${D.items[id]?.name||id}"><small>${i+1}</small>${icon(id)}<b>${s.inventory[id]||''}</b></div>`).join('');paintIcons()}
function refresh(){hud();if(!$('#panelLayer').classList.contains('hide'))openPanel($('#panelLayer').dataset.panel)}function showAnalysis(a){$('#analyseName').textContent=a.name;$('#analyseText').textContent=a.text;$('#analyseFacts').innerHTML=a.facts.map(f=>`<dt>${f[0]}</dt><dd>${f[1]}</dd>`).join('');$('#analyseCard').classList.remove('hide')}
function openPanel(type){if(!G.state&&type!=='system')return;G.setPaused(true);$('#panelLayer').dataset.panel=type;$('#panelLayer').classList.remove('hide');let titles={inventory:'INVENTORY & EQUIPMENT',craft:'CRAFTING',quests:'QUEST JOURNAL',shop:'ONLINE SHOP',map:'WORLD MAP',system:'SAVE MANAGEMENT'};$('#panelTitle').textContent=titles[type];$('#panelEyebrow').textContent=type==='shop'?'ARCANE SUPPLY NETWORK':'FIELD SYSTEM';$('#panelContent').innerHTML=({inventory:inventoryPanel,craft:craftPanel,quests:questPanel,shop:shopPanel,map:mapPanel,system:systemPanel}[type])();paintIcons()}
function closePanel(){if(!$('#panelLayer').classList.contains('hide')){$('#panelLayer').classList.add('hide');if(G.state)G.setPaused(false)}}
function inventoryPanel(){let s=G.state,rows=Object.entries(s.inventory).filter(x=>x[1]>0).map(([id,q])=>{let i=D.items[id]||{name:id,desc:''},usable=['berry','ration','bottle','water_dirty'].includes(id);return`<div class="item-row"><div class="item-icon">${icon(id)}</div><div><h3>${i.name}</h3><p>${i.desc}</p></div><div><b>×${q}</b>${usable?`<button class="action-btn" data-use="${id}">USE</button>`:''}</div></div>`}).join('')||'<p>Your pockets are empty.</p>';return`<div class="inventory-summary"><span>PACK ${C.usedCapacity(s,D.items).toFixed(1)} / ${s.player.capacity} KG</span><span>EQUIPPED: HANDS</span><span>⌁ ${s.player.credits}</span></div>${rows}`}
function craftPanel(){let s=G.state;return`<div class="grid">${D.recipes.map(r=>{let locked=s.player.rank<r.rank,can=Object.entries(r.cost).every(([id,q])=>(s.inventory[id]||0)>=q),out=Object.keys(r.makes)[0];return`<article class="card ${locked?'locked':''}"><div class="card-art">${icon(out,true)}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="meta">${Object.entries(r.cost).map(([id,q])=>`${q} ${D.items[id].name} (${s.inventory[id]||0})`).join(' • ')}</div><div class="meta">⏱ ${r.minutes} MINUTES</div><footer><span>${locked?'RANK '+r.rank:can?'READY':'MISSING MATERIALS'}</span><button data-craft="${r.id}" ${!can||locked?'disabled':''}>CRAFT</button></footer></article>`}).join('')}</div>`}
function questPanel(){let s=G.state;return s.quests.map(q=>{let ready=!q.claimed&&q.objectives.every(o=>o.current>=o.target);return`<article class="quest-row ${q.claimed?'complete':''}"><h3>${q.claimed?'✓ ':''}${q.title}</h3><p>${q.desc}</p>${q.objectives.map(o=>`<div class="qrow">${o.label}: ${o.current}/${o.target}</div>`).join('')}<footer><span>REWARD ${q.xp} XP • ⌁ ${q.credits}</span>${ready?`<button class="action-btn" data-claim="${q.id}">CLAIM REWARD</button>`:q.claimed?'<b>COMPLETED</b>':''}</footer></article>`}).join('')}
function shopPanel(){let s=G.state;return`<div class="inventory-summary"><span>CATALOG REFRESH: RANK ${s.player.rank+1}</span><b>AVAILABLE BALANCE: ⌁ ${s.player.credits}</b></div><div class="grid">${D.shop.map(e=>{let i=D.items[e.id]||e,locked=s.player.rank<e.rank;return`<article class="card ${locked?'locked':''}"><div class="card-art">${icon(e.id,true)}</div><h3>${i.name}</h3><p>${i.desc}</p><div class="meta">${e.cat} • ${locked?'REQUIRES RANK '+e.rank:'IN STOCK'}</div><footer><b class="price">⌁ ${e.price}</b><button data-buy="${e.id}" ${locked?'disabled':''}>${locked?'LOCKED':'PURCHASE'}</button></footer></article>`}).join('')}</div>`}
function mapPanel(){let s=G.state;return`<p class="inventory-summary">Fog lifts as Darwin enters a region. ${s.discovered.length}/${D.zones.length} mapped.</p><div class="map-canvas">${D.zones.map(z=>`<div class="map-zone ${s.discovered.includes(z.id)?'':'unknown'}" style="left:${z.x/21}%;top:${z.y/16}%;width:${z.w/21}%;height:${z.h/16}%">${z.name}</div>`).join('')}</div>`}
function systemPanel(){let m=g.TLS_SAVE.meta();return`<div class="save-card"><b>AUTOSAVE SLOT</b><p>${m?`Day ${m.day}, Level ${m.level} • ${new Date(m.savedAt).toLocaleString()}`:'No save data'}</p><button class="action-btn" data-save>MANUAL SAVE</button></div><div class="save-card"><b>LOCAL & OFFLINE</b><p>Progress is stored only in this browser. Corrupt saves automatically fall back to the previous snapshot.</p></div><button class="action-btn danger" data-delete>DELETE SAVE & NEW GAME</button>`}
function confirm(title,text,action){confirmAction=action;$('#confirmTitle').textContent=title;$('#confirmText').textContent=text;$('#confirmLayer').classList.remove('hide')}
document.addEventListener('click',e=>{let t=e.target.closest('button');if(!t)return;if(t.dataset.panel)openPanel(t.dataset.panel);if(t.dataset.action==='analyse')G.analyse();if(t.dataset.action==='interact')G.interact();if(t.dataset.close)$('#'+t.dataset.close).classList.add('hide');if(t.dataset.use){G.useItem(t.dataset.use);openPanel('inventory')}if(t.dataset.craft){let r=D.recipes.find(x=>x.id===t.dataset.craft),res=C.craft(G.state,r,D.items);G.log(res.ok?`Crafted ${r.name}.`:res.reason);toast(res.ok?'Crafting complete':res.reason);refresh()}if(t.dataset.buy){let x=D.shop.find(x=>x.id===t.dataset.buy),i=D.items[x.id]||x;confirm(`Purchase ${i.name}?`,`Spend ${x.price} Credits. Items cannot be returned.`,()=>{let res=C.purchase(G.state,x,D.items);if(res.ok){G.log(`Online Shop delivered ${i.name}.`);toast('Purchase delivered')}else toast(res.reason);refresh()})}if(t.dataset.claim){let q=G.state.quests.find(x=>x.id===t.dataset.claim);if(C.claimQuest(G.state,q)){G.log(`Quest complete: ${q.title}.`);toast(`+${q.xp} XP • +${q.credits} Credits`);refresh()}}if(t.hasAttribute('data-save')){G.save();toast('Progress saved locally')}if(t.hasAttribute('data-delete'))confirm('Delete save?','This permanently removes local progress and starts a new game.',()=>{g.TLS_SAVE.clear();location.reload()})});
$('#closePanel').onclick=closePanel;$('#confirmNo').onclick=()=>$('#confirmLayer').classList.add('hide');$('#confirmYes').onclick=()=>{let a=confirmAction;$('#confirmLayer').classList.add('hide');confirmAction=null;if(a)a()};$('#newGame').onclick=()=>{$('#titleScreen').classList.add('hide');$('#storyScreen').classList.remove('hide');storyStep=0;$('#storyText').textContent=stories[0]};$('#storyNext').onclick=()=>{storyStep++;if(storyStep<stories.length)$('#storyText').textContent=stories[storyStep];else{$('#storyScreen').classList.add('hide');G.start(G.newState())}};$('#continueGame').onclick=()=>{let s=g.TLS_SAVE.load();if(s)G.start(s);else toast('Save could not be recovered')};$('#manageSave').onclick=()=>{let m=g.TLS_SAVE.meta();confirm(m?'Saved expedition found':'No saved expedition',m?`Day ${m.day}, Level ${m.level}. Delete it and begin again?`:'No local save data exists.',m?()=>{g.TLS_SAVE.clear();location.reload()}:null)};if(g.TLS_SAVE.has())$('#continueGame').hidden=false;g.TLS_UI={hud,refresh,toast,showAnalysis,openPanel,closePanel};})(window);
